SEND_POLICIES = ('off', 'local', 'redact', 'refuse')

def model_local(model=None) -> bool:
    "Whether `model`, an id or a built chat, runs on this machine; a chat that names no runtime, or an id Urai cannot place, counts as hosted."
    if model is not None and not isinstance(model, str): return is_local(getattr(model, 'runtime', None))
    try: return is_local(urai().resolve_runtime(model or dflt_model)[0])
    except Exception: return False

def send_rule(level:str, local:bool, policy:str='redact', allow:bool=False, image:bool=False) -> str:
    "Decide how one item goes to a model, `whole`, `masked` or `withheld`, from its level, whether the model is local, the policy, `allow`, and whether it is an image."
    if policy not in SEND_POLICIES: raise ValueError(f'unknown pii policy: {policy!r}; one of {SEND_POLICIES}')
    if local or level == 'open': return 'whole'
    if level == 'local': return 'withheld'
    if allow or policy == 'off': return 'whole'
    return 'masked' if policy == 'redact' and not image else 'withheld'

def send_line(items, model_name:str, local:bool) -> str:
    "The sentence that tells a person where a send goes and how many items go whole, masked or withheld."
    unit = 'page' if any(i.get('page') is not None for i in items) else 'document'
    def say(lv, how, n):
        u = f"{unit}{'' if n == 1 else 's'}"
        return f'{n} {u} open' if lv == 'open' else f"{n} {lv.replace('local', 'local-only')} {u} {how}"
    c = Counter((i.level, i.how) for i in items)
    return (f"{model_name or 'default model'}, {'on this machine' if local else 'hosted'}. "
            + (', '.join(say(*k, n) for k, n in c.items()) or 'nothing to send') + '.')

@patch
def send_check(self:Vault,
               refs=None,           # documents: a doc_id, source or title, or a list of them
               pages=None,          # pages: `(ref, page)` pairs or `{doc_id, page}` dicts
               text=None,           # text with no document behind it: a string or a list of them
               model=None,          # an id or a built chat; None -> $VISHALAKSHI_MODEL
               policy:str='redact', # off|local|redact|refuse: what a hosted model gets of a Personal item
               allow:bool=False,    # allow once: Personal items go whole; Local only still never does
               image:bool=False,    # the items go as page images, which cannot be masked
               level:str=None,      # a level the items start at, above what they would have
               ner:bool=True,       # look for names in `text` too
) -> AttrDict:
    "Decide, before a send, which documents, pages or texts go to `model` whole, masked or withheld, with a sentence saying so."
    loc = model_local(model)
    name = model if isinstance(model, str) else getattr(model, 'model', None) or (None if model is not None else dflt_model)
    items = L()
    def add(lv, kinds, **kw):
        lv = top(lv, level)
        items.append(AttrDict(kw, level=lv, kinds=kinds, how=send_rule(lv, loc, policy, allow, image)))
    for r in L(refs if isinstance(refs, (list, tuple, L)) else [refs] if refs is not None else []):
        v = self.level(r); add(v.level, v.kinds, doc_id=v.doc_id, page=None, title=v.title)
    for p in L(pages or []):
        did, pg = (p.get('doc_id'), p.get('page')) if isinstance(p, dict) else p
        v = self.level(did, page=pg); add(v.level, v.kinds, doc_id=v.doc_id, page=pg, title=v.title)
    for t in L(text if isinstance(text, (list, tuple, L)) else [text] if text is not None else []):
        rep = pii_report(t, ner=ner)
        add(top(self.floor(), 'personal' if rep.has_pii else 'open'), rep.identifying, doc_id=None, page=None, text=t)
    for i in items:
        if i.get('text') is not None and i.how == 'masked': i.text = redact(i.text, ner=ner)
        elif i.get('text') is not None and i.how == 'withheld': i.text = held(i.kinds or {i.level: 1})
    wh = items.filter(lambda i: i.how == 'withheld')
    kinds = dict(sum((Counter(i.kinds) for i in items if i.level != 'open'), Counter()))
    kind = None if not wh else 'local_only' if all(i.level == 'local' for i in wh) else 'pii_blocked'
    rt = getattr(model, 'runtime', None) if model is not None and not isinstance(model, str) else None
    return AttrDict(ok=not wh, local=loc, model=name, runtime=rt, policy=policy, allow=allow, kind=kind, kinds=kinds, rows=items,
                    send=items.filter(lambda i: i.how != 'withheld'), masked=items.filter(lambda i: i.how == 'masked'), withheld=wh,
                    why=send_line(items, name, loc))

@patch
def _send_log_t(self:Vault):
    t = self.db.t.send_log
    if not t.exists():
        with write_txn(self.db): t.create(id=str, at=float, store=str, doc_id=str, pages=str, model=str, runtime=str, policy=str, kinds=str, pk='id')
    return t

@patch
def _sent(self:Vault, chk, model=None, runtime=None):
    "Log a send that left the machine, one row per document; a local send is not logged."
    if chk is None or chk.local: return
    by = {}
    for i in chk.send:
        if i.get('doc_id'): by.setdefault(i.doc_id, []).append(i.page)
    if not by: return
    t, now = self._send_log_t(), time.time()
    with write_txn(self.db):
        for did, pgs in by.items():
            t.insert(dict(id=uuid.uuid4().hex[:12], at=now, store=self.name, doc_id=did, pages=json.dumps([p for p in pgs if p is not None]), model=str(model or chk.model or ''),
                          runtime=str(runtime or chk.runtime or ''), policy=chk.policy, kinds=json.dumps(chk.kinds)))

@patch
def sends(self:Vault, ref=None, limit:int=100) -> L:
    "Read the send log, newest first: what went to a hosted model, when and to which model, for one document when `ref` names it."
    if not self.db.t.send_log.exists(): return L()
    w, a = 'store=?', [self.name]
    if ref is not None and (d := self.doc(ref)): w, a = w + ' and doc_id=?', a + [d['id']]
    return L(self.db.t.send_log.rows_where(w, a, order_by='at desc', limit=limit)).map(
        lambda r: AttrDict(r, pages=json.loads(r['pages'] or '[]'), kinds=json.loads(r['kinds'] or '{}')))


# %% ../nbs/02_ask.ipynb #42db118cfc970f35
def _scrub_answer(out, private:bool, ner:bool=True):
    """Mask identifiers the model reproduced anyway. Returns `(out, leaked)` kinds."""
    if not private: return out
    if out.get('fields') is not None:
        r = pii_report(str(out.fields), ner=ner)
        if r.has_pii: out.fields, out.leaked = redact_obj(out.fields, ner=ner), r.identifying
    elif out.get('answer'):
        r = pii_report(out.answer, ner=ner)
        if r.has_pii: out.answer, out.leaked = redact(out.answer, ner=ner), r.identifying
    return out

LOCAL_OK = None   #: None probes; True/False decides for a host that already knows

def local_ok(model:str=None) -> bool:
    "Whether the runtime that `model`, by default the PII model, resolves to runs on this machine and is installed."
    if (ok := _here().LOCAL_OK) is not None: return bool(ok)
    try:
        rt, _ = urai().resolve_runtime(model or pii_model_)
        if not is_local(rt): return False
        from urai.opts import RUNTIMES, load_ref
        load_ref(RUNTIMES[rt].cls); return True
    except Exception: return False

def ask_policy(pii:str=None, model:str=None) -> str:
    "The policy `ask` applies: the one given, or by default `local` when a local runtime is installed and `redact` when not; `off` gets the default."
    if pii == 'off': warnings.warn("pii='off' does not apply to ask; using the default policy", stacklevel=2)
    if pii in (None, 'off'): return 'local' if local_ok(model) else 'redact'
    if pii not in ('local', 'redact', 'refuse'): raise ValueError(f'unknown pii policy for ask: {pii!r}; one of local|redact|refuse')
    return pii

@patch
def ask(self:Vault,
        question:str,          # what you want to know
        ref=None,              # documents to ask about: a doc_id, source, title or path, or a list of them
        schema=None,           # answer as this shape instead of prose: a SCHEMAS key, dataclass, or 'field:type' spec
        model:str=None,        # an id, a path, `mlx/…`; None -> $VISHALAKSHI_MODEL
        chat_kw:dict=None,     # anything else Urai's `Chat` takes: temp, runtime, think, …
        sections:int=4,        # operative sections retrieved
        related:int=6,         # associative sections offered as leads
        kind:str=None,         # restrict retrieval to one or more KINDS
        code:int=None,         # code sections to add; None -> 4 if kosha has indexed the repo
        dir:str=None,          # repo for the code legs; None -> the cwd repo
        max_chars:int=1500,    # chars of each retrieved section shown to the model
        doc_chars:int=8000,    # chars of `ref`'s documents shown to the model, shared between them
        sp:str=VAULT_SP,       # system prompt
        mk_chat=None,          # build chats with this instead of `new_chat`; same signature
        pii:str=None,          # local|redact|refuse; None -> local when a local runtime exists, else redact
        pii_model:str=None,    # the local model that answers then; None -> $VISHALAKSHI_PII_MODEL
        pii_ner:bool=True,     # also look for names that follow a title such as Dr; a pattern, not a model
        instruction:str='',    # an instruction from the questioner, for a second turn
        **kw                   # forwarded to Vault.context
) -> AttrDict:
    "Answer a question from the vault, or about the documents `ref` names, citing the numbered sections the answer used."
    pii, mid = ask_policy(pii, pii_model), model or dflt_model
    mk = lambda: (mk_chat or new_chat)(model, sp=sp, **(chat_kw or {}))
    if ref is None:
        ctx, note, mc = self.context(question, sections=sections, related=related, kind=kind, code=code,
                                     dir=dir, **kw), '', max_chars
    else:
        ctx = self.doc_context(ref, question, related=related, max_chars=doc_chars)
        note, mc = ctx.note, doc_chars
    report, lv = self._ctx_gate(ctx, pii, pii_ner, keep=int(ctx.get('n_docs') or 0))
    private = report.has_pii
    if private and pii == 'local': note = f"{note}These sections hold personal information ({', '.join(sorted(report.identifying))}). "
    if instruction: question = f'{question}\n\nInstruction from the questioner: {instruction}'
    if private and pii == 'local':
        mid = pii_model or pii_model_
        mk = lambda: (mk_chat or new_chat)(pii_model or pii_model_, sp=PII_SP, **(chat_kw or {}))
    ch = mk()
    chk = self._ctx_send(ctx, lv, ch, pii, mid)
    prompt = mk_prompt(question, ctx, max_chars=mc, related=bool(related), note=note)
    d = ctx.get('doc')
    out = AttrDict(question=question, model=mid, runtime=ch.runtime, context=ctx, encoder=self.enc.note,
            prompt=prompt, answer=None, thinking='', cited=L(), schema=None, fields=None, **(dict(doc_id=d.doc_id,
            title=d.title, source=d.source, origin=d.origin, chars=sum(len(x.text) for x in ctx.docs),
            truncated=any(ctx.docs.attrgot('truncated'))) if d else {}))
    out.pii, out.policy, out.send, out.level = report, pii, chk, top(*lv.values())
    if private and pii != 'redact':
        rt = str(getattr(ch, 'runtime', '') or '')
        if pii == 'refuse' or not is_local(rt):
            out.answer = (f"held back: these sections hold personal information "
                          f"({', '.join(sorted(report.identifying))}) and "
                          + ('the policy is to refuse' if pii == 'refuse' else
                             f'{rt or "this"} is not a local runtime, so nothing was sent to it'))
            out.refused = True
            return out
    if schema is not None:
        from vishalakshi.extract import as_schema, structured
        sch = as_schema(schema, name='Answer', doc=f'The answer to: {question}')
        sys_sp = PII_SP if private and pii == 'local' else sp
        out.schema, out.fields = sch.__name__, structured(ch, prompt, sch, sp=sys_sp)
        out = _scrub_answer(out, private)
    else:
        try: res = ch(prompt)
        except Exception as e:
            if not (urai().is_ctx_error(ch, e) or isinstance(e, (RuntimeError, ValueError))): raise
            warnings.warn(f'{type(e).__name__} on a {len(prompt)}-char prompt ({e}); retrying with less '
                          f'context. Lower `sections`/`doc_chars`/`max_chars`, or use a model with a '
                          f'bigger window.')
            ctx.results, ctx.related = ctx.results[:2], L()
            out.prompt = prompt = mk_prompt(question, ctx, max_chars=mc//3, related=False, note=note)
            ch = mk()
            res = ch(prompt)
        out.answer, out.thinking = split_reasoning(urai().resp_text(res))
        out.answer, out.thinking = out.answer.strip(), out.thinking or urai().thought(res)
        out.cited = cited(out.answer, ctx.results)
        out = _scrub_answer(out, private)
    self._sent(chk, mid, ch.runtime)
    out.usage = getattr(ch, 'use', None)
    return self._observe(out)     # records the citations as labels, when learning is on

@patch
def explain(self:Vault, node_id:str, model:str=None, chat_kw:dict=None, max_chars:int=6000,
            sp:str=VAULT_SP, mk_chat=None,
            pii:str=None,          # local|redact|refuse; None -> local when a local runtime exists, else redact
            pii_model:str=None, pii_ner:bool=True) -> AttrDict:
    "Have a model explain one section and say what related sections in the vault add to it or contradict."
    pii = ask_policy(pii, pii_model)
    sec, rel = self.read(node_id, max_chars=max_chars), self.related(node_id, limit=6)
    row = AttrDict(node_id=node_id, doc_id=node_id.split('#')[0], store=sec.get('store'), title=sec.get('title', ''),
                   breadcrumb=sec.get('title', ''), text=sec.get('text', ''))
    ctx = AttrDict(results=L([row]), related=L(AttrDict(r) for r in rel))
    report, lv = self._ctx_gate(ctx, pii, pii_ner)
    private, mid, sys_sp = report.has_pii, model or dflt_model, sp
    out = AttrDict(node_id=node_id, pii=report, policy=pii, level=lv.get(_rkey(row, self.name)) or 'open')
    if private and pii == 'refuse':
        return AttrDict(out, answer=f"held back: section holds personal information ({', '.join(sorted(report.identifying))})", refused=True)
    if private and pii == 'local': mid, sys_sp = pii_model or pii_model_, PII_SP
    ch = (mk_chat or new_chat)(mid, sp=sys_sp, **(chat_kw or {}))
    out.runtime = ch.runtime
    if private and pii == 'local' and not is_local(getattr(ch, 'runtime', '')):
        return AttrDict(out, answer=f"held back: section holds personal information and {ch.runtime} is not local", refused=True)
    out.send = chk = self._ctx_send(ctx, lv, ch, pii, mid)
    s = ctx.results[0]
    if s.get('held'): return AttrDict(out, answer=s.text, refused=True)
    out.prompt = prompt = (f"Section: {s.title}\n\n{s.text}\n\nOther sections in the vault that read like it:\n" +
                           '\n'.join(f"- {r['breadcrumb']}" for r in ctx.related) +
                           "\n\nExplain this section, then say what the related sections add or contradict.")
    res = ch(prompt)
    answer, thinking = split_reasoning(urai().resp_text(res))
    self._sent(chk, mid, ch.runtime)
    out.update(answer=answer.strip(), thinking=thinking or urai().thought(res), section=sec, related=rel, model=mid)
    return _scrub_answer(out, private)


